#!/bin/sh
# Feeds the topology.conf generated by ibnetlens to a real slurmctld and checks that the tree plugin accepts it.
# Needs the slurmctld daemon:  apt install slurmctld      dnf install slurm-slurmctld
# Without root, unpack the packages and point SLURMPREFIX at the unpacked tree.
#
# usage: xcheck-slurm.sh PATH_TO_IBNETLENS FIXTURE.topo [FIXTURE ...]
set -u
BIN=$1
shift
TMP=$(mktemp -d)
CTLD_PID=
stop_ctld() {
    [ -z "$CTLD_PID" ] && return
    pkill -KILL -P "$CTLD_PID" 2>/dev/null
    kill -KILL "$CTLD_PID" 2>/dev/null
    wait "$CTLD_PID" 2>/dev/null
    CTLD_PID=
}
cleanup() {
    stop_ctld
    rm -rf "$TMP"
}
trap cleanup EXIT INT TERM

P=${SLURMPREFIX:-}
CTLD=
for n in slurmctld slurmctld-wlm; do
    for d in $P/usr/sbin $P/usr/bin $P/sbin; do
        [ -x "$d/$n" ] && { CTLD=$d/$n; break 2; }
    done
    c=$(command -v "$n" 2>/dev/null) && { CTLD=$c; break; }
done
if [ -z "$CTLD" ]; then
    echo "skip real slurmctld check (slurmctld not found)"
    exit 0
fi
PLUGDIR=
for d in $P/usr/lib/x86_64-linux-gnu/slurm-wlm $P/usr/lib64/slurm $P/usr/lib/slurm $P/usr/lib/aarch64-linux-gnu/slurm-wlm; do
    [ -f "$d/topology_tree.so" ] && { PLUGDIR=$d; break; }
done
if [ -n "$P" ]; then
    LD_LIBRARY_PATH=$P/usr/lib/x86_64-linux-gnu:$P/usr/lib/x86_64-linux-gnu/slurm-wlm:$P/usr/lib64${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}
    export LD_LIBRARY_PATH
fi
if [ -z "$PLUGDIR" ]; then
    echo "skip real slurmctld check (topology_tree plugin not found)"
    exit 0
fi

fail=0
ok()  { printf 'ok   %s\n' "$1"; }
bad() { printf 'FAIL %s\n' "$1"; fail=1; }

for fixture in "$@"; do
    name=$(basename "$fixture")
    D=$TMP/$name
    mkdir -p "$D/state" "$D/etc"
    "$BIN" -F slurm "$fixture" > "$D/etc/topology.conf" 2>/dev/null
    switches=$(grep -c '^SwitchName=' "$D/etc/topology.conf")
    {
        echo "ClusterName=xcheck"
        echo "SlurmctldHost=localhost"
        echo "SlurmUser=$(id -un)"
        echo "AuthType=auth/none"
        echo "CredType=cred/none"
        echo "SlurmctldPort=$((20000 + $$ % 20000))"
        echo "StateSaveLocation=$D/state"
        echo "SlurmctldPidFile=$D/pid"
        echo "SlurmctldLogFile=$D/log"
        echo "PluginDir=$PLUGDIR"
        echo "ProctrackType=proctrack/linuxproc"
        echo "TaskPlugin=task/none"
        echo "SelectType=select/cons_tres"
        echo "TopologyPlugin=topology/tree"
        grep -o 'Nodes=[^ ]*' "$D/etc/topology.conf" | cut -d= -f2 | sort -u | while read -r list; do
            echo "NodeName=$list CPUs=1 State=UNKNOWN"
        done
        echo "PartitionName=all Nodes=ALL Default=YES State=UP"
    } > "$D/etc/slurm.conf"

    "$CTLD" -D -f "$D/etc/slurm.conf" -vvv > "$D/out" 2>&1 &
    CTLD_PID=$!
    sleep 4
    stop_ctld
    [ -s "$D/log" ] && cat "$D/log" >> "$D/out"

    if grep -q 'cannot find auth plugin\|cannot create auth context' "$D/out"; then
        echo "skip real slurmctld check (the auth/none plugin is not installed; try slurm-auth-none)"
        stop_ctld
        exit 0
    fi
    loaded=$(grep -c 'Switch level:' "$D/out")
    # only topology-related complaints count; MailProg, PMIx and state-file errors are environment noise
    errors=$(grep -iE 'fatal|(error|invalid|duplicate|fail).*(topolog|switch)|(topolog|switch).*(error|invalid|duplicate|fail)' "$D/out" | grep -vc 'Switch level')
    if [ "$loaded" -ge "$switches" ] && [ "$errors" -eq 0 ] && [ "$switches" -gt 0 ]; then
        ok "slurmctld accepts $name ($switches switches)"
    else
        bad "slurmctld rejects $name (loaded $loaded of $switches switches, $errors errors)"
        grep -iE 'fatal|error|invalid|duplicate|topolog|switch' "$D/out" | head -8
    fi
done
# the reason ibnetlens gives a spine that serves hosts a synthetic leaf: Slurm refuses a switch with both lists
D=$TMP/both
mkdir -p "$D/state" "$D/etc"
printf 'SwitchName=leaf1 Nodes=n[1-3]\nSwitchName=leaf2 Nodes=n[4-6]\nSwitchName=spine Switches=leaf[1-2] Nodes=login\n' > "$D/etc/topology.conf"
{
    echo "ClusterName=xcheck"
    echo "SlurmctldHost=localhost"
    echo "SlurmUser=$(id -un)"
    echo "AuthType=auth/none"
    echo "CredType=cred/none"
    echo "SlurmctldPort=$((20000 + ($$ + 1) % 20000))"
    echo "StateSaveLocation=$D/state"
    echo "SlurmctldPidFile=$D/pid"
    echo "SlurmctldLogFile=$D/log"
    echo "PluginDir=$PLUGDIR"
    echo "ProctrackType=proctrack/linuxproc"
    echo "TaskPlugin=task/none"
    echo "SelectType=select/cons_tres"
    echo "TopologyPlugin=topology/tree"
    echo "NodeName=n[1-6],login CPUs=1 State=UNKNOWN"
    echo "PartitionName=all Nodes=ALL Default=YES State=UP"
} > "$D/etc/slurm.conf"
"$CTLD" -D -f "$D/etc/slurm.conf" -vvv > "$D/out" 2>&1 &
CTLD_PID=$!
sleep 4
stop_ctld
[ -s "$D/log" ] && cat "$D/log" >> "$D/out"
if grep -q 'has both child switches and nodes' "$D/out"; then
    ok "slurmctld rejects a switch that has both Switches= and Nodes="
else
    bad "slurmctld did not reject a switch that has both Switches= and Nodes= (the synthetic leaf may no longer be needed)"
fi
exit $fail
